import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, DoubleSide } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, uniform, texture, fract, sin, dot, clamp } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  root.name = 'pricing-title';

  const content = new Group();
  root.add(content);

  // ---- Palette (spec exact) ----
  const INK = new THREE.Color('#16161d');
  const SURFACE = new THREE.Color('#0b0b10');
  const ACCENT = new THREE.Color('#ff2a38');
  const PAPER = '#e8ecf2';

  const inkVec = vec3(INK.r, INK.g, INK.b);
  const surfaceVec = vec3(SURFACE.r, SURFACE.g, SURFACE.b);
  const accentVec = vec3(ACCENT.r, ACCENT.g, ACCENT.b);

  // ---- Backdrop card (engineered gradient + grain + thin accent band) ----
  const cardW = 3.6;
  const cardH = 1.2;
  const cardGeo = new PlaneGeometry(cardW, cardH, 1, 1);

  const vUv = uv();

  // vertical gradient ink -> near-black surface
  const gradient = mix(surfaceVec, inkVec, vUv.y);

  // subtle procedural grain
  const grainSeed = dot(vUv, vec2(12.9898, 78.233));
  const grain = fract(sin(grainSeed).mul(43758.5453123));
  const grainCentered = grain.sub(0.5).mul(0.035);

  // thin accent band near bottom edge (~8% of card height, well under 10% frame rule)
  const bandLow = smoothstep(0.0, 0.02, vUv.y);
  const bandHigh = smoothstep(0.09, 0.07, vUv.y);
  const band = bandLow.mul(bandHigh);
  const withGrain = gradient.add(vec3(grainCentered, grainCentered, grainCentered));
  const baseColor = mix(withGrain, accentVec, band.mul(0.85));

  const textureMix = uniform(0.0);
  let liveTextureNode = null;

  const cardMat = new MeshBasicNodeMaterial({ side: DoubleSide, transparent: false });
  cardMat.colorNode = clamp(baseColor, 0.0, 1.0);

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0);
  content.add(cardMesh);

  // ---- Optional isolated hero texture, subtly blended into the gradient ----
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      liveTextureNode = texture(tex, vUv);
      cardMat.colorNode = clamp(mix(baseColor, liveTextureNode, textureMix), 0.0, 1.0);
      cardMat.needsUpdate = true;
      gsap.to(textureMix, { value: 0.22, duration: 0.9, ease: 'power2.out' });
    }).catch(() => {});
  }

  // ---- Headline text: "Pricing" ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? { text: 'Pricing', typography: { fontSize: 96 } };

  const headline = ctx.fontAtlas.createText(headlineItem.text ?? 'Pricing', {
    fontSize: headlineItem.typography?.fontSize ?? 96,
    color: PAPER,
    align: 'center',
  });
  headline.position.set(0, 0, 0.03);
  content.add(headline);

  // ---- Motion: weighted entrance + one slow idle breathing transform ----
  content.position.y = 0.4;
  content.scale.setScalar(0.98);

  const tl = gsap.timeline();
  tl.to(content.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  tl.to(content.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  }, 0.05);

  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 0.8 });
  idleTl.to(content.scale, {
    x: 1.02, y: 1.02, z: 1.02,
    duration: 3.2,
    ease: 'sine.inOut',
  });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    idleTl.kill();
    cardGeo.dispose();
    cardMat.dispose();
    if (headline?.geometry) headline.geometry.dispose();
    if (headline?.material) headline.material.dispose();
    if (headline?.userData?.cleanup) headline.userData.cleanup();
  };

  return root;
}
